+:root {
+  color-scheme: dark;
+  --bg: #0b1020;
+  --panel: #121a30;
+  --panel-strong: #18233f;
+  --text: #edf2ff;
+  --muted: #b5c0e0;
+  --accent: #7ca8ff;
+  --accent-strong: #a8c2ff;
