 const form = document.getElementById("quiz-form");
 const feedback = document.getElementById("quiz-feedback");

 const answers = {
   q1: ["python", "rust", "sql"],
   q2: ["javascript", "css", "html"],
   q3: ["python", "java"],
 };

 function selectedValues(name) {
   return [...form.querySelectorAll(`input[name="${name}"]:checked`)].map(
     (input) => input.value
   );
 }

 function isExactMatch(selected, correct) {
   if (selected.length !== correct.length) {
     return false;
   }

   return correct.every((value) => selected.includes(value));
 }

 form.addEventListener("submit", (event) => {
   event.preventDefault();

   const score = Object.entries(answers).reduce((total, [name, correct]) => {
     return total + (isExactMatch(selectedValues(name), correct) ? 1 : 0);
   }, 0);

   feedback.textContent = `You got ${score} out of 3 correct.`;
 });

