 :root {
   color-scheme: dark;
   --bg: #0b1020;
   --panel: #121a30;
   --panel-strong: #18233f;
   --text: #edf2ff;
   --muted: #b5c0e0;
   --accent: #7ca8ff;
   --accent-strong: #a8c2ff;
   --border: #2b3a63;
   --focus: #f5c96a;
   --success: #82e6b6;
 }

 * {
   box-sizing: border-box;
 }

 html {
   scroll-behavior: smooth;
 }

 body {
   margin: 0;
   min-height: 100vh;
   background:
     radial-gradient(circle at top, #17213f 0%, var(--bg) 50%);
   color: var(--text);
   font: 16px/1.5 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
 }

 a {
   color: var(--accent-strong);
 }

 a:focus-visible,
 button:focus-visible,
 input:focus-visible {
   outline: 3px solid var(--focus);
   outline-offset: 3px;
 }

 .skip-link {
   position: absolute;
   left: 1rem;
   top: 1rem;
   transform: translateY(-200%);
   padding: 0.75rem 1rem;
   border-radius: 999px;
   background: var(--panel-strong);
   color: var(--text);
   text-decoration: none;
   transition: transform 0.2s ease;
   z-index: 10;
 }

 .skip-link:focus {
   transform: translateY(0);
 }

 .shell {
   width: min(100%, 56rem);
   margin: 0 auto;
   padding: 0 1.25rem;
 }

 .page-header {
   padding: 3rem 0 1.25rem;
 }

 .eyebrow {
   margin: 0 0 0.5rem;
   text-transform: uppercase;
   letter-spacing: 0.16em;
   color: var(--accent-strong);
   font-size: 0.78rem;
 }

 h1 {
   margin: 0;
   font-size: clamp(2rem, 5vw, 3.5rem);
   line-height: 1.1;
 }

 .lede {
   margin: 0.75rem 0 0;
   max-width: 40rem;
   color: var(--muted);
 }

 .quiz-card {
   display: grid;
   gap: 1rem;
   padding: 1.25rem;
   margin-bottom: 2rem;
   border: 1px solid var(--border);
   border-radius: 1.25rem;
   background: linear-gradient(180deg, rgba(24, 35, 63, 0.95), rgba(18, 26, 48, 0.98));
   box-shadow: 0 18px 40px rgba(0, 0, 0, 0.25);
 }

 .form-field {
   padding: 1rem;
   border: 1px solid var(--border);
   border-radius: 1rem;
   background: var(--panel);
 }

 .question-group {
   margin: 0;
   padding: 0;
   border: 0;
 }

 legend {
   padding: 0;
   font-size: 1.1rem;
   font-weight: 700;
 }

 .help-text {
   margin: 0.35rem 0 0;
   color: var(--muted);
 }

 .choices {
   display: grid;
   grid-template-columns: repeat(auto-fit, minmax(12rem, 1fr));
   gap: 0.75rem;
   margin-top: 1rem;
 }

 .choice {
   display: flex;
   align-items: center;
   gap: 0.75rem;
   padding: 0.9rem 1rem;
   border: 1px solid var(--border);
   border-radius: 0.875rem;
   background: var(--panel-strong);
   color: var(--text);
   cursor: pointer;
 }

 .choice:hover {
   border-color: var(--accent);
 }

 .choice input {
   width: 1.1rem;
   height: 1.1rem;
   margin: 0;
   accent-color: var(--accent);
 }

 .actions {
   display: flex;
   justify-content: flex-end;
   padding-top: 0.25rem;
 }

 .submit-button {
   border: 1px solid transparent;
   border-radius: 999px;
   padding: 0.9rem 1.3rem;
   background: linear-gradient(180deg, var(--accent-strong), var(--accent));
   color: #07101f;
   font: inherit;
   font-weight: 700;
   cursor: pointer;
 }

 .submit-button:hover {
   filter: brightness(1.05);
 }

 .feedback {
   min-height: 1.5rem;
   margin: 0;
   color: var(--success);
 }

 @media (max-width: 40rem) {
   .page-header {
     padding-top: 2rem;
   }

   .quiz-card {
     padding: 1rem;
   }

   .form-field {
     padding: 0.875rem;
   }

   .actions {
     justify-content: stretch;
   }

   .submit-button {
     width: 100%;
   }
 }

 @media (forced-colors: active) {
   :root {
     --bg: Canvas;
     --panel: Canvas;
     --panel-strong: Canvas;
     --text: CanvasText;
     --muted: CanvasText;
     --accent: Highlight;
     --accent-strong: HighlightText;
     --border: ButtonBorder;
     --focus: Highlight;
     --success: CanvasText;
   }

   .quiz-card,
   .form-field,
   .choice,
   .submit-button,
   .skip-link {
     forced-color-adjust: auto;
   }

   .submit-button {
     color: ButtonText;
     background: ButtonFace;
   }
 }

